import pathlib
from playwright.sync_api import sync_playwright
URL = pathlib.Path(__file__).resolve().parent.parent.joinpath("index.html").as_uri()
res = []
def ok(name, cond, extra=""):
    res.append(bool(cond)); print(("PASS" if cond else "FAIL"), name, extra)
n = lambda pg: pg.locator("#grid li").count()
with sync_playwright() as p:
    b = p.chromium.launch(); pg = b.new_page(viewport={"width":1280,"height":800}); errs = []
    pg.on("console", lambda m: errs.append(m.text) if m.type in ("error","warning") else None)
    pg.on("pageerror", lambda e: errs.append(str(e)))
    pg.goto(URL)
    ok("CSS carregado (fundo do hero escuro)", pg.evaluate("getComputedStyle(document.querySelector('.hero')).backgroundColor") == "rgb(17, 17, 17)")
    ok("12 produtos", n(pg) == 12); ok("6 cartões de categoria", pg.locator(".cat").count() == 6)
    ok("Sem imagens quebradas (arquivos ausentes viram espaço identificado)", pg.evaluate("[...document.images].every(i=>i.complete&&i.naturalWidth>0)"))
    ok("Espaços de foto identificados", pg.locator(".ph").count() > 20)
    pg.click(".cat[data-cat=Camisetas]"); ok("Categoria Camisetas -> 3", n(pg) == 3)
    pg.click("nav a[data-cat=Moletons]"); ok("Menu Moletons -> 3", n(pg) == 3)
    pg.click("#clear"); pg.fill("#q","cargo"); ok("Busca 'cargo' -> 1", n(pg) == 1)
    pg.fill("#q","calca"); ok("Busca sem acento 'calca' -> 2", n(pg) == 2)
    pg.fill("#q","zzz"); ok("Sem resultado mostra aviso", "Nenhum produto" in pg.inner_text("#count"))
    pg.click("#clear"); pg.select_option("#price","0-100"); ok("Preço até R$ 100 -> 3", n(pg) == 3)
    pg.click("#clear"); pg.check("#fNew"); ok("Novidades -> 3", n(pg) == 3)
    pg.click("#clear"); pg.check("#fBest"); ok("Mais vendidos -> 5", n(pg) == 5)
    pg.click("#clear"); pg.select_option("#sort","asc"); ok("Menor preço primeiro", "79,90" in pg.inner_text("#grid li >> nth=0"))
    pg.select_option("#sort","desc"); ok("Maior preço primeiro", "399,90" in pg.inner_text("#grid li >> nth=0"))
    pg.click("#clear")
    pg.click("[data-add='4']"); pg.click("[data-add='4']"); ok("Badge da sacola = 2", pg.inner_text("#bagCount") == "2")
    pg.click("#bagBtn"); pg.wait_for_selector("#bag.show"); ok("Sacola abre com subtotal R$ 499,80", "499,80" in pg.inner_text("#subtotal"))
    pg.click("[data-inc='4']"); ok("Quantidade aumenta (badge 3)", pg.inner_text("#bagCount") == "3")
    pg.click("[data-dec='4']"); pg.click("#closeBag"); pg.reload(); ok("Sacola persiste após recarregar", pg.inner_text("#bagCount") == "2")
    pg.click("#bagBtn"); pg.wait_for_selector("#bag.show"); pg.click("[data-rm='4']"); ok("Remover esvazia a sacola", pg.inner_text("#bagCount") == "0" and pg.locator("#bagEmpty").is_visible())
    pg.click("#closeBag"); pg.wait_for_selector(".offcanvas-backdrop", state="detached")
    pg.click("[data-view='7'] >> nth=0"); pg.wait_for_selector("#viewDlg.show"); ok("Visualização do produto abre", pg.locator("#viewDlg").is_visible()); pg.click("#vClose"); pg.wait_for_selector(".modal-backdrop", state="detached")
    f = pg.inner_text(".slide.on h3"); pg.click("#next"); ok("Carrossel avança", pg.inner_text(".slide.on h3") != f)
    pg.click(".dot >> nth=2"); ok("Indicador leva ao slide 3", pg.inner_text("#pos") == "Slide 3 de 3")
    pg.click("#pause"); ok("Pausar", pg.get_attribute("#pause","aria-pressed") == "true")
    pg.click("#openA11y"); pg.wait_for_selector("#a11y.show"); fs0 = pg.evaluate("parseFloat(getComputedStyle(document.documentElement).fontSize)")
    pg.click("#fontUp"); ok("Fonte aumenta", pg.evaluate("parseFloat(getComputedStyle(document.documentElement).fontSize)") > fs0)
    pg.click("#fontReset"); t0 = pg.get_attribute("html","data-theme"); pg.click("#themeBtn"); ok("Tema alterna", pg.get_attribute("html","data-theme") != t0)
    pg.click("#themeBtn"); pg.check("#contrastChk"); ok("Alto contraste", pg.get_attribute("html","data-contrast") == "high"); pg.uncheck("#contrastChk")
    pg.keyboard.press("Escape"); pg.wait_for_selector("#a11y:not(.show)", state="attached"); pg.wait_for_selector(".offcanvas-backdrop", state="detached"); ok("Esc fecha painel", not pg.locator("#a11y").is_visible())
    pg.fill("#cName","a"); pg.fill("#cEmail","x"); pg.fill("#cSubject","i"); pg.fill("#cMsg","oi"); pg.click("#contactForm button[type=submit]")
    ok("Contato inválido: 4 erros e foco no 1º", all(pg.inner_text(f"#{i}Err") for i in ("cName","cEmail","cSubject","cMsg")) and pg.evaluate("document.activeElement.id")=="cName")
    pg.fill("#cName","Ana Lima"); pg.fill("#cEmail","ana@email.com"); pg.fill("#cSubject","Troca"); pg.fill("#cMsg","Quero trocar um tamanho."); pg.click("#contactForm button[type=submit]")
    ok("Contato válido envia", pg.input_value("#cName") == "" and pg.locator("#toast").is_visible())
    pg.click("#openLogin"); pg.wait_for_selector("#loginDlg.show"); pg.fill("#lEmail","ruim"); pg.fill("#lPass","123"); pg.click("#loginForm button[type=submit]"); ok("Login inválido mostra erros", pg.inner_text("#lEmailErr") and pg.inner_text("#lPassErr"))
    pg.screenshot(path="prints/04-login-erro.png")
    pg.fill("#lEmail","x"); pg.click("#forgot"); ok("Recuperar senha valida e-mail", pg.inner_text("#lEmailErr") != "")
    pg.fill("#lEmail","a@b.com"); pg.fill("#lPass","123456"); pg.click("#loginForm button[type=submit]"); pg.wait_for_selector("#loginDlg:not(.show)", state="attached"); ok("Login válido", pg.inner_text("#openLogin").lower() == "sessão ativa")
    ok("Um h1; campos com label", pg.locator("h1").count()==1 and pg.evaluate("[...document.querySelectorAll('input:not([type=checkbox]),textarea')].every(i=>document.querySelector(`label[for=${i.id}]`))"))
    ok("Sem overflow horizontal (desktop)", pg.evaluate("document.documentElement.scrollWidth<=innerWidth"))
    pg.evaluate("localStorage.clear()"); pg.reload(); pg.evaluate("document.documentElement.dataset.theme='light'; scrollTo(0,0)")
    pg.wait_for_timeout(1200); pg.screenshot(path="prints/01-inicio-claro.png")
    pg.locator("#cats").scroll_into_view_if_needed(); pg.screenshot(path="prints/02-colecao.png")
    pg.click("#openA11y"); pg.wait_for_selector("#a11y.show"); pg.click("#themeBtn"); pg.click("#fontUp"); pg.wait_for_timeout(300); pg.screenshot(path="prints/03-escuro-acessibilidade.png")
    pg.screenshot(path="prints/05-pagina-completa-escuro.png", full_page=True)
    for name,w,h in (("tablet",768,1024),("celular",375,812)):
        m = b.new_page(viewport={"width":w,"height":h}); m.goto(URL)
        ok(f"Sem overflow ({name} {w}px)", m.evaluate("document.documentElement.scrollWidth<=innerWidth"), str(m.evaluate("document.documentElement.scrollWidth")))
        if w == 375:
            ok("Menu móvel: nav oculta até abrir", not m.locator("#nav").is_visible()); m.click("#menuBtn"); m.wait_for_selector("#nav.show"); ok("Menu móvel abre", m.locator("#nav").is_visible())
            ok("Login e acessibilidade visíveis no celular", m.locator("#openLogin").is_visible() and m.locator("#openA11y").is_visible())
            m.screenshot(path="prints/07-menu-celular.png"); m.click("#menuBtn")
        m.screenshot(path=f"prints/06-{name}.png"); m.close()
    ok("Console sem erros/avisos", not errs, str(errs)); b.close()
print(f"\n{sum(res)}/{len(res)} testes passaram")
